package dev.pedro.learning.ecommerce.payment.provider;
import jakarta.enterprise.context.ApplicationScoped;import org.eclipse.microprofile.faulttolerance.*;import org.eclipse.microprofile.rest.client.inject.RestClient;import java.time.temporal.ChronoUnit;import java.util.concurrent.atomic.AtomicInteger;
@ApplicationScoped public class PaymentProviderGateway{private final FakePaymentProviderClient client;private final AtomicInteger fallbacks=new AtomicInteger();public PaymentProviderGateway(@RestClient FakePaymentProviderClient client){this.client=client;}
 @Timeout(value=600,unit=ChronoUnit.MILLIS)@Retry(maxRetries=1,delay=100,delayUnit=ChronoUnit.MILLIS,jitter=0)@CircuitBreaker(requestVolumeThreshold=4,failureRatio=0.5,delay=3,delayUnit=ChronoUnit.SECONDS,successThreshold=2)@Fallback(fallbackMethod="fallback")
 public ProviderPaymentResponse pay(ProviderPaymentRequest request){return client.pay(request);}public ProviderPaymentResponse fallback(ProviderPaymentRequest request){fallbacks.incrementAndGet();return ProviderPaymentResponse.failed("Provider unavailable, timed out, or circuit open");}public int fallbackCount(){return fallbacks.get();}public void resetStats(){fallbacks.set(0);}}
